begin
 select string_agg(distinct i,', ') into missing from jsonb_array_elements(plan) e(r) cross join lateral jsonb_array_elements_text(coalesce(e.r->'shopItems','[]'::jsonb)) i
  where not exists(select 1 from eldervale_private.realm_catalog c where c.id='item:'||i);
 if missing is not null then raise exception 'Capital stock missing from the catalog: %',missing;end if;
 update eldervale_private.settings set revision=revision+1 where id returning revision into rev;
 for r in select value from jsonb_array_elements(plan) loop
  if exists(select 1 from eldervale_private.entities where not deleted and data->>'blueprint'='birchford-capital-v1' and data->>'blueprintKey'=r->>'blueprintKey') then continue;end if;
  d:=r-'shopItems';
  if r ? 'shopItems' then
   select jsonb_object_agg(i,jsonb_build_object('buy',(c.data->>'buy')::integer,'sell',(c.data->>'sell')::integer,'stock',-1)) into shop
    from jsonb_array_elements_text(r->'shopItems') i join eldervale_private.realm_catalog c on c.id='item:'||i;
   d:=d||jsonb_build_object('shop',shop);
  end if;
  insert into eldervale_private.entities(id,revision,data) values(gen_random_uuid(),rev,d);added:=added+1;
 end loop;
 -- Dressing that stood where the walls, streets and doors now are.
 update eldervale_private.entities set deleted=true,revision=rev where not deleted and id::text in ('2d7567ea-4ac1-4133-94fb-3f2ba4aee918','0cdae8f8-7081-4493-9663-c2850af40dd8','b1cf8b31-8538-441b-a1b3-22f6752459b7','69c3a609-af3f-4eb2-88f3-e0467e11071b','90329b1d-0c03-400f-94f7-a3562671bb43');
 -- The forest stops at the walls: seeded trees inside are never available (no collision, no chopping).
 update eldervale_private.realm_objects set available_at='infinity' where kind='tree' and id like 'base:tree:%' and point(x,z)<@polygon '((-274,74),(-201.51,74),(-162,113.51),(-162,192.49),(-181.51,212),(-254.49,212),(-274,192.49))' and available_at is distinct from 'infinity';
 -- Gates and business doors stand open.
 update eldervale_private.realm_objects o set open=true where not o.open and o.id in (select id::text from eldervale_private.entities where not deleted and data->>'blueprint'='birchford-capital-v1')
  and (o.kind='castle_gate' or (o.kind='door' and eldervale_private.door_held_open(o.id)));
 -- Town zone (sanctuary) covers the walled city.
 update eldervale_private.town_zones set x=-218,z=143,radius=66,square=true where id='Birchford';
 if added=0 then update eldervale_private.settings set revision=revision-1 where id;end if;
 raise notice 'Birchford capital: % entities added',added;
end $seed$;

-- Sanity report: counts by template, gates open, shops stocked.
select data->>'template' as template,count(*) from eldervale_private.entities where not deleted and data->>'blueprint'='birchford-capital-v1' group by 1 order by 1;
select e.data->>'name' as gate,o.open from eldervale_private.entities e join eldervale_private.realm_objects o on o.id=e.id::text where e.data->>'blueprint'='birchford-capital-v1' and e.data->>'template'='castle_gate' and not e.deleted;
select e.data->>'name' as merchant,(select count(*) from eldervale_private.shop_stock s where s.merchant=e.id::text) as stock_rows from eldervale_private.entities e where e.data->>'blueprint'='birchford-capital-v1' and e.data->>'template'='merchant' and not e.deleted order by 1;
